// Photography albums: one per shoot folder on the photo drive, kept in the
// `albums` content collection (src/content/albums/*.yaml, generated by
// `npm run photos:albums -- build`). A nested file is a sub-album: its path is
// its link, so 2026-otakon-2026/day-1.yaml is /photography/2026-otakon-2026/day-1.
// The photos themselves are read from Cloudinary by id (api/cloudinary/album),
// so nothing is tagged there. Server only.
import { getCollection } from "astro:content";
import { CLOUD_NAME } from "./cloudinary";
import { hashOf, type AlbumCard, type AlbumView, type StackPhoto } from "./albumData";
import { cloudinaryTransform } from "./cloudinaryImage";

export type Album = {
  title: string;
  /** The full link: "2026-otakon-2026/day-1". */
  path: string;
  /** `YYYY-MM-DD`, or null when nothing in the album is dated (label shows the year). */
  date: string | null;
  year: number;
  /** Photos in it and everything beneath it. */
  count: number;
  /** Its own photos: Cloudinary public_ids, in capture order. Server-only: never sent to the island. */
  photos: string[];
  /** Up to three ids. */
  cover: string[];
  /** Shown sub-albums, newest first. */
  subs: Album[];
  /** From the top-level album down to this one. */
  crumbs: Album[];
};

/** An album with no sub-albums is shown from this many photos. */
export const MIN_ALBUM_PHOTOS = 5;

const parentOf = (path: string) => path.slice(0, Math.max(0, path.lastIndexOf("/")));

/** Newest first, undated ones as January 1st of their year. */
const newestFirst = (a: Album, b: Album) =>
  (b.date ?? `${b.year}-01-01`).localeCompare(a.date ?? `${a.year}-01-01`) || a.title.localeCompare(b.title);

type Entry = { id: string; data: { title: string; year: number; date: Date | null; photos: string[] } };

/** The shown albums, as a tree. A sub-album whose parent isn't there (or isn't
 *  shown) isn't shown: there would be no way to it. */
export function buildAlbums(entries: readonly Entry[]): { top: Album[]; byPath: Map<string, Album> } {
  const children = Map.groupBy(entries, ({ id }) => parentOf(id));
  const byPath = new Map<string, Album>();
  const build = (parent: string, above: Album[]): { shown: Album[]; count: number } => {
    let count = 0;
    const shown: Album[] = [];
    for (const { id, data } of children.get(parent) ?? []) {
      const album: Album = {
        title: data.title,
        path: id,
        date: data.date ? data.date.toISOString().slice(0, 10) : null,
        year: data.year,
        count: data.photos.length,
        photos: data.photos,
        cover: data.photos.slice(0, 3),
        subs: [],
        crumbs: [],
      };
      album.crumbs = [...above, album];
      const beneath = build(id, album.crumbs);
      album.subs = beneath.shown;
      album.count += beneath.count;
      count += album.count;
      if (children.has(id) || album.photos.length >= MIN_ALBUM_PHOTOS) shown.push(album);
    }
    for (const album of shown) byPath.set(album.path, album);
    return { shown: shown.sort(newestFirst), count };
  };
  return { top: build("", []).shown, byPath };
}

const albums = async () => buildAlbums(await getCollection("albums"));

/** The top-level albums that are shown, newest first. */
export const listAlbums = async (): Promise<Album[]> => (await albums()).top;

/** Every shown album by its link. */
export const albumsByPath = async (): Promise<Map<string, Album>> => (await albums()).byPath;

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/** Stack label: `May 2026 · 24 photos`, or `2024 · 12 photos` when undated. */
export function albumDetails({ date, year, count }: Pick<Album, "date" | "year" | "count">): string {
  const when = date ? `${MONTHS[Number(date.slice(5, 7)) - 1]} ${date.slice(0, 4)}` : String(year);
  return `${when} · ${count} ${count === 1 ? "photo" : "photos"}`;
}

const STACK_CARD_TRANSFORM = "c_fill,w_352,h_440,f_auto,q_auto";

export const toStackPhoto = (publicId: string, cloudName = CLOUD_NAME): StackPhoto => ({
  key: publicId,
  src: cloudinaryTransform(`https://res.cloudinary.com/${cloudName}/image/upload/${publicId}`, STACK_CARD_TRANSFORM),
});

export const toAlbumCard = (album: Album): AlbumCard => ({
  path: album.path,
  title: album.title,
  details: albumDetails(album),
  previews: album.cover.map((id) => toStackPhoto(id)),
  version: albumVersion(album),
});

/** What the gallery needs to show an album, besides its photos. */
export const toAlbumView = (album: Album): AlbumView => ({
  path: album.path,
  title: album.title,
  crumbs: album.crumbs.map(({ path, title }) => ({ path, title })),
  tiles: album.subs.map(toAlbumCard),
});

/** Changes with anything its data URL returns: its photos and their order, its
 *  place, and its sub-albums (each card's own version included). */
export const albumVersion = (album: Album): string => hashOf(JSON.stringify([toAlbumView(album), album.photos]));

/** A shared album link's preview image: the cover, cropped to the 1200×630
 *  Open Graph card. JPEG, since link scrapers don't all take WebP/AVIF. */
export const toOgImage = (publicId: string, cloudName = CLOUD_NAME): string =>
  cloudinaryTransform(`https://res.cloudinary.com/${cloudName}/image/upload/${publicId}`, "c_fill,g_auto,w_1200,h_630,f_jpg,q_auto");
